<script setup lang="ts">
import { reactive,watch,ref } from 'vue';
import { FolderOpen,Globe,RefreshCw,ShieldCheck,Save,Server,KeyRound } from '@lucide/vue';
import { desk,safely,saveProject,request,apiPath,operation,refresh,notify,openBrowse } from './store';
const project=reactive({displayName:'',sourceDirectory:'',publicBaseUrl:''}),settings=reactive({httpHost:'',httpPort:8080,webHost:'',webPort:18080});
const account=reactive({username:'',password:'',newPassword:'',confirmPassword:'',allowLocalBypass:false});
const address=ref<any>(null);
watch(()=>desk.project,()=>{Object.assign(project,{displayName:desk.project?.displayName||'',sourceDirectory:desk.project?.sourceDirectory||'',publicBaseUrl:desk.project?.publicBaseUrl||''});desk.settingsDirty=false;},{immediate:true});
watch(()=>desk.state.settings,()=>Object.assign(settings,desk.state.settings||{}),{immediate:true});
watch(()=>desk.auth,()=>{account.username=desk.auth.username||'';account.allowLocalBypass=Boolean(desk.auth.localBypass);},{immediate:true});
watch(()=>desk.browseValues['project-source'],value=>{if(value){project.sourceDirectory=value;desk.settingsDirty=true;}});
async function checkAddress(){address.value=await request(apiPath('/check-address'),'POST',{url:project.publicBaseUrl});}
async function saveService(){await operation(async()=>{await request('/api/settings','PUT',settings);await refresh();notify('服务设置已保存');});}
async function saveAccount(){if(account.newPassword!==account.confirmPassword)throw new Error('两次新密码不一致');await operation(async()=>{await request('/api/auth/account','PUT',account);account.password='';account.newPassword='';account.confirmPassword='';desk.auth=await request('/api/auth/status');notify('账户设置已保存');});}
</script>
<template><section class="settings-workspace"><header class="view-toolbar"><div><strong>{{desk.section==='service'?'服务设置':desk.section==='account'?'账户与安全':'项目设置'}}</strong><span>{{desk.section==='project'?desk.project?.displayName:'当前管理连接'}}</span></div></header>
 <form v-if="desk.section!=='service'&&desk.section!=='account'" class="settings-form" @submit.prevent="safely(()=>saveProject(project))" @input="desk.settingsDirty=true"><h3>整合包项目</h3><label>项目名称<input v-model="project.displayName" required></label><label>整合包标准目录<div class="field-with-button"><input v-model="project.sourceDirectory" required><button type="button" @click="openBrowse('directory','project-source',project.sourceDirectory)"><FolderOpen :size="16"/></button></div><small>模组与配置从这个目录检查并发布。</small></label><label>玩家更新地址<input v-model="project.publicBaseUrl" type="url" required></label><button type="button" @click="safely(checkAddress)"><Globe :size="15"/>检测地址</button><p v-if="address" class="field-help">{{address.message||address.summary||address.status||'检测完成'}}</p><div class="settings-save"><span v-if="desk.settingsDirty">有尚未保存的修改</span><button class="accent" :disabled="desk.busy"><Save :size="15"/>保存项目设置</button></div><dl class="metadata-list"><dt>项目 ID</dt><dd>{{desk.project?.id}}</dd><dt>管理数据</dt><dd>{{desk.state.dataDirectory}}</dd></dl></form>
 <form v-else-if="desk.section==='service'" class="settings-form" @submit.prevent="safely(saveService)"><h3>玩家下载服务</h3><p>下载地址用于提供更新内容，与管理工作区的地址分别设置。</p><div class="form-grid"><label>监听地址<input v-model="settings.httpHost" required></label><label>监听端口<input v-model.number="settings.httpPort" type="number" min="1" max="65535" required></label></div><button type="button" @click="desk.dialog='service'"><Server :size="15"/>查看下载服务状态</button><h3>网页管理服务</h3><div class="form-grid"><label>网页监听地址<input v-model="settings.webHost" required></label><label>网页端口<input v-model.number="settings.webPort" type="number" min="1" max="65535" required></label></div><small>桌面工作区使用自动分配的本机端口，原网页配置仍保留。</small><div class="settings-save"><button class="accent" :disabled="desk.busy"><Save :size="15"/>保存服务设置</button></div></form>
 <form v-else class="settings-form" @submit.prevent="safely(saveAccount)"><div class="security-heading"><ShieldCheck :size="27"/><div><h3>管理账户</h3><p>当前账户 {{desk.auth.username||'管理员'}}</p></div></div><label>用户名<input v-model="account.username" autocomplete="username" required></label><label>当前密码<input v-model="account.password" type="password" autocomplete="current-password" required></label><h3>修改密码</h3><label>新密码<input v-model="account.newPassword" type="password" autocomplete="new-password" minlength="10"></label><label>确认新密码<input v-model="account.confirmPassword" type="password" autocomplete="new-password"></label><label class="check"><input v-model="account.allowLocalBypass" type="checkbox">允许在管理服务本机免登录</label><div class="settings-save"><button class="accent" :disabled="desk.busy"><KeyRound :size="15"/>保存账户设置</button></div></form>
</section></template>
